import{_ as s,C as i,o as t,c as n,a2 as r,b as d,w as a,a as l,E as h,a3 as c}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Trash Bin Pro","description":"Soft-delete trash bin for the Pterodactyl file manager with restorable files, per-server and per-egg quotas, retention windows, and a full admin panel.","frontmatter":{"title":"Trash Bin Pro","description":"Soft-delete trash bin for the Pterodactyl file manager with restorable files, per-server and per-egg quotas, retention windows, and a full admin panel."},"headers":[],"relativePath":"trash-bin-pro/index.md","filePath":"trash-bin-pro/index.md","lastUpdated":1785512893000}'),p={name:"trash-bin-pro/index.md"};function g(u,e,b,m,y,v){const o=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=r('<h1 id="trash-bin-pro" tabindex="-1">Trash Bin Pro <a class="header-anchor" href="#trash-bin-pro" aria-label="Permalink to &quot;Trash Bin Pro&quot;">​</a></h1><p><strong>Recoverable file deletion for Pterodactyl Panel</strong> — a soft-delete trash bin for the client file manager, available as a Blueprint extension or a standalone panel installer. Deleted files are moved to a hidden <code>/.trash</code> folder on the game server instead of being destroyed, tracked in MySQL, and can be restored with collision-safe naming until a configurable retention window expires — at which point an hourly purge removes them for good.</p><p>Trash Bin Pro gives game-server owners the safety net every desktop OS has had for decades, without giving up disk control: hosting-grade quotas per server, per egg, or globally, a dedicated <code>trashbinpro.access</code> sub-user permission, and full activity logging so every trash, restore, and purge is auditable.</p><div class="tip custom-block" style="margin-top:1.5rem;"><p><strong>Built for PingLess Studios by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">AnAverageBeing</a></strong><a href="https://github.com/AnAverageBeing/pterodactyl-trash-bin-pro" target="_blank" rel="noreferrer">GitHub Repo</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Studio</a></p></div><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',6)),(t(),d(c,null,{default:a(()=>[h(o,{id:"mermaid-18",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20Panel%5BPterodactyl%20Panel%5D%0A%20%20%20%20%20%20%20%20SPA%5BClient%20SPA%20File%20Manager%5D%20--%3E%20FC%5BFileController%20-%20patched%5D%0A%20%20%20%20%20%20%20%20FC%20--%3E%20TS%5BTrashService%5D%0A%20%20%20%20%20%20%20%20TS%20--%3E%20SETTINGS%5BTrashBinSettingsRepository%20-%205%20min%20cache%5D%0A%20%20%20%20%20%20%20%20TS%20--%3E%20ACT%5BTrashActivityLogger%5D%0A%20%20%20%20%20%20%20%20SETTINGS%20--%3E%20DB%5B(trashbin_*%20tables)%5D%0A%20%20%20%20%20%20%20%20TS%20--%3E%20DB%0A%20%20%20%20%20%20%20%20SCHED%5BHourly%20Scheduler%5D%20--%3E%20PURGE%5BPurgeTrashCommand%5D%0A%20%20%20%20%20%20%20%20PURGE%20--%3E%20DB%0A%20%20%20%20%20%20%20%20ADMIN%5BAdmin%20Panel%20%2Fadmin%2Ftrashbinpro%5D%20--%3E%20SETTINGS%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Node%5BWings%20Node%5D%0A%20%20%20%20%20%20%20%20TS%20--%3E%7CHTTPS%20%2B%20Bearer%7C%20WINGS%5BWings%20DaemonFileRepository%5D%0A%20%20%20%20%20%20%20%20PURGE%20--%3E%7Cdelete%20expired%20batch%7C%20WINGS%0A%20%20%20%20%20%20%20%20WINGS%20--%3E%20TRASHDIR%5B%2F.trash%20folder%20in%20container%5D%0A%20%20%20%20end%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r(`<p>The <strong>panel</strong> owns all state: which files are trashed, where they originally lived, who deleted them, and when the retention window expires. The <strong>game server</strong> holds the actual bytes — files live in a hidden <code>/.trash</code> directory inside the container, moved there through the same Wings <code>DaemonFileRepository</code> the stock file manager uses. No node-side daemon, no extra ports, no cron edits: the hourly purge is scheduled by the service provider.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Soft delete</strong> — deleted files are moved to a hidden <code>/.trash</code> folder on the server instead of being destroyed; the stock hard delete stays one click away via a permanent-delete flow.</li><li><strong>Restore with collision-safe naming</strong> — files return to their original path; if something already occupies that name, the restore becomes <code>name (restored)</code>, <code>name (restored 2)</code>, and so on.</li><li><strong>Disk quotas</strong> — cap trash usage per server, per egg, or globally (0 = unlimited). A single file larger than the cap, or a bin that would overflow, is rejected with a structured HTTP 409 and the UI offers a guarded <strong>Delete Permanently</strong> alternative.</li><li><strong>Retention windows</strong> — per-server, per-egg, or global retention in hours (1–8760). Expired entries are removed by the hourly <code>p:trashbin:purge</code> run.</li><li><strong>Fault-tolerant hourly purge</strong> — chunked <code>chunkById</code> batches, one Wings call per server, per-server try/catch so one unreachable node never blocks the rest, and failed servers are retried on the next run.</li><li><strong>Sub-user permission</strong> — <code>trashbinpro.access</code> controls who can view, restore from, and empty the trash bin; enforced server-side on every client route.</li><li><strong>Activity logging</strong> — every trash, restore, purge, and empty event is written to Pterodactyl&#39;s built-in activity log (<code>server:trashbinpro.*</code>).</li><li><strong>Full admin panel</strong> — <code>/admin/trashbinpro</code>: global settings, per-egg overrides, top servers by trash usage, and a manual <strong>Purge Now</strong> button.</li><li><strong>Idempotent installer</strong> — every PHP and React/TypeScript patch is marker-guarded and check-before-insert per block; reinstalling is a zero-diff no-op.</li><li><strong>Trash Bin protects itself</strong> — server-side guards refuse to trash the <code>/.trash</code> directory itself, and ghost rows (files already gone from disk) are cleaned up instead of erroring.</li></ul><hr><h2 id="stock-pterodactyl-vs-trash-bin-pro" tabindex="-1">Stock Pterodactyl vs Trash Bin Pro <a class="header-anchor" href="#stock-pterodactyl-vs-trash-bin-pro" aria-label="Permalink to &quot;Stock Pterodactyl vs Trash Bin Pro&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Stock Pterodactyl</th><th>Trash Bin Pro</th></tr></thead><tbody><tr><td>Delete behavior</td><td>Hard delete — file is gone immediately</td><td>Move to <code>/.trash</code>, tracked in MySQL</td></tr><tr><td>Recovery window</td><td>None</td><td>Configurable retention (hours), per server / egg / global</td></tr><tr><td>Restore</td><td>Not possible</td><td>One click, collision-safe naming</td></tr><tr><td>Quotas</td><td>None — N/A, nothing is kept</td><td>Per-server, per-egg, and global byte caps</td></tr><tr><td>Permissions</td><td><code>file.delete</code> only</td><td>Adds <code>trashbinpro.access</code> for view/restore/empty</td></tr><tr><td>Audit trail</td><td>Delete event only</td><td>Trash, restore, purge, and empty all logged</td></tr><tr><td>Permanent delete</td><td>The only option</td><td>Explicit guarded flow with confirmation checkbox</td></tr></tbody></table><hr><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><p><strong>Blueprint (recommended):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactyltrashbinpro-v1.0.2</span></span></code></pre></div><p><strong>Standalone (no Blueprint):</strong> copy <code>standalone/PanelFiles</code> into the panel, then run <code>standalone/data/install.sh</code> with <code>PTERODACTYL_DIRECTORY</code> set. Either way, rebuild the client SPA afterwards:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:production</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Scheduler requirement</p><p>The hourly purge runs through Laravel&#39;s scheduler, registered by the service provider — no <code>Kernel.php</code> edit needed. You only need the standard Pterodactyl cron entry (<code>* * * * * php /var/www/pterodactyl/artisan schedule:run</code>) already in place.</p></div><hr><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><strong>Delete</strong> — the user deletes files in the file manager. The patched <code>FileController::delete()</code> intercepts the request and calls <code>TrashService::trashFiles()</code>, which validates quotas and refuses the trash directory itself.</li><li><strong>Move + record</strong> — a <code>trashbin_files</code> row is created per file (original path, size, mode, who deleted it), then Wings renames each file into <code>/.trash/{id}</code> — the row id doubles as the on-disk name, so the bin never has name collisions.</li><li><strong>Restore or manage</strong> — from the Trash view (toolbar button in the file manager), users with <code>trashbinpro.access</code> can restore files to their original path, delete individual entries permanently, or empty the bin. Name collisions on restore are resolved automatically.</li><li><strong>Hourly purge</strong> — <code>p:trashbin:purge</code> runs every hour via the scheduler, walks <code>trashbin_files</code> in chunks, applies each server&#39;s effective retention window, and deletes expired files from Wings and the database in one call per server.</li></ol><hr><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Target</th></tr></thead><tbody><tr><td>Pterodactyl Panel</td><td>v1.11.x / v1.12.x</td></tr><tr><td>Laravel / PHP</td><td>Laravel 11, PHP 8.2+</td></tr><tr><td>Blueprint</td><td><code>beta-2026-05</code></td></tr><tr><td>Version</td><td><code>1.0.2</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Trash counts against real disk</p><p>Files in <code>/.trash</code> still occupy the server&#39;s disk allocation. Set capacity limits in <strong>Admin → Trash Bin Pro</strong> so a busy trash bin cannot starve a server of working space.</p></div>`,21))])}const w=s(p,[["render",g]]);export{k as __pageData,w as default};
